import 'dart:io';

/// Writes `tips.g.dart` from a text file with one tip per line.
///
/// Usage: gen_tips TIPS_TXT OUTPUT
void main(List<String> arguments) {
  if (arguments.length != 2) {
    stderr.writeln('usage: gen_tips TIPS_TXT OUTPUT');
    exit(2);
  }
  final tips = File(arguments[0])
      .readAsLinesSync()
      .where((line) => line.trim().isNotEmpty)
      .map((line) => "'${line.trim()}'")
      .join(', ');
  File(arguments[1]).writeAsStringSync(
    '// Generated by gen_tips. Do not edit.\n'
    'const List<String> tips = <String>[$tips];\n',
  );
}
